def refs():
    return [{**s, "subject": "math", "locator": "正方形、長方形、箏形的邊角條件、對角線性質與圖形判定", "observedPattern": "公開學校數學試題常以特殊四邊形的邊、角、平行與對角線條件考查圖形辨識及充分條件；本題只取能力方向。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]

def make(i, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-math-content-s-8-10-{i}", "subject": "math", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三份公立學校公開數學試題僅供特殊四邊形性質與判定能力方向研究；未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公立學校公開數學試題的特殊四邊形方向獨立改寫；題幹、數值、選項、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}

Q = [
make(1, "正方形具有哪一組基本性質？", {"A":"四邊等長且四角皆為直角","B":"只有一組對邊平行","C":"四邊都不等長且四角相等","D":"只有兩邊等長"}, "A", "正方形同時具備四邊等長與四個直角，選 A。", "先分別核對邊長條件和角度條件，再確認是否同時成立。", ["正方形有四條邊。","四條邊長度相等。","四個內角都是 90°。","A 同時包含兩項必要性質。","選 A。"], "easy"),
make(2, "長方形的兩條對角線具有什麼關係？", {"A":"互相垂直且不等長","B":"等長且互相平分","C":"只互相平分，不一定等長","D":"一定互不相交"}, "B", "長方形的對角線等長，且因為它是平行四邊形而互相平分，選 B。", "合併長方形與平行四邊形的性質，不把正方形特性誤套到所有長方形。", ["長方形是平行四邊形的特例。","因此對角線互相平分。","長方形再增加四角為直角。","其對角線也等長。","選 B。"], "medium"),
make(3, "箏形的定義最符合下列哪一項？", {"A":"兩組相鄰邊分別等長","B":"兩組對邊分別平行","C":"四邊全部等長且四角直角","D":"只有一組鄰邊等長"}, "A", "箏形有兩組相鄰邊分別等長，選 A。", "看邊的相鄰／相對位置，不能把箏形和菱形的四邊等長混同。", ["箏形是四邊形。","找出一組相鄰等長邊。","另一組相鄰邊也等長。","這兩組條件構成箏形定義。","選 A。"], "easy"),
make(4, "正方形、長方形、箏形三者中，哪個圖形一定同時是長方形與平行四邊形？", {"A":"正方形","B":"箏形","C":"任意四邊形","D":"只有一般梯形"}, "A", "正方形四角為直角，因此是長方形；對邊平行，因此也是平行四邊形，選 A。", "用包含關係逐層檢查：正方形具備長方形和行四邊形的條件。", ["正方形四角都是直角。","所以符合長方形定義。","正方形對邊平行。","所以也符合平行四邊形定義。","選 A。"], "medium"),
make(5, "一個平行四邊形若有一個內角是 90°，通常可判定它是什麼？", {"A":"長方形","B":"一般梯形","C":"箏形","D":"任意四邊形"}, "A", "平行四邊形的鄰角互補；若一角 90°，其餘各角也為 90°，因此是長方形，選 A。", "使用平行四邊形的角關係把一個直角推到四個角。", ["已知一角是 90°。","鄰角與它互補，所以也是 90°。","對角相等，得到第四角也 90°。","四角直角符合長方形。","選 A。"], "medium"),
make(6, "正方形的兩條對角線通常具有哪組關係？", {"A":"等長、互相垂直且互相平分","B":"不等長、平行且不相交","C":"只等長，不相交","D":"只垂直，不平分"}, "A", "正方形的對角線等長、互相垂直並互相平分，選 A。", "分別檢查等長、垂直、平分三項，而不是只記其中一項。", ["正方形是長方形，對角線等長。","正方形是菱形，對角線互相垂直。","正方形是平行四邊形，對角線互相平分。","三項性質同時成立。","選 A。"], "medium"),
make(7, "箏形的兩條對角線通常具有哪一項性質？", {"A":"互相垂直","B":"一定等長","C":"互相平行","D":"都不相交"}, "A", "箏形的兩條對角線互相垂直；但不一定等長或互相平分，選 A。", "只取箏形必然具備的性質，避免借用正方形或長方形的對角線條件。", ["箏形有兩組相鄰邊等長。","其對稱對角線會垂直另一條對角線。","所以兩對角線互相垂直。","等長與平分不是一般箏形必然條件。","選 A。"], "medium"),
make(8, "若一個四邊形四邊等長且四個角都是直角，它必定是什麼？", {"A":"正方形","B":"一般平行四邊形但不是正方形","C":"一般箏形但不是正方形","D":"一般梯形"}, "A", "四邊等長給出菱形條件，四角直角給出長方形條件，兩者合併就是正方形，選 A。", "將邊與角分開判定，再取兩種特殊四邊形條件的交集。", ["四邊等長表示具有菱形性質。","四角直角表示具有長方形性質。","同時具備兩者即為正方形。","所以選 A。","回查四邊與四角條件皆符合。"], "medium"),
make(9, "下列哪個條件足以判定平行四邊形是長方形？", {"A":"一組對邊等長","B":"一個內角為 90°","C":"兩條鄰邊等長","D":"一條對角線較長"}, "B", "平行四邊形只要有一個直角，便可推出四角皆直角，判定為長方形，選 B。", "判定題先使用已知的平行四邊形前提，再尋找新增的直角條件。", ["題目已保證是平行四邊形。","檢查哪個選項提供直角證據。","一個內角 90°可由鄰角互補與對角相等推廣。","四角直角即為長方形。","選 B。"], "medium"),
make(10, "下列哪項最能區分一般長方形與正方形？", {"A":"正方形還要求四邊等長","B":"正方形沒有直角","C":"長方形一定沒有平行邊","D":"兩者對角線都不相交"}, "A", "長方形只要求四角直角；正方形在此之外還要求四邊等長，選 A。", "找出正方形比長方形多出的限制條件。", ["長方形具有四個直角。","正方形也具有四個直角。","因此直角不能區分兩者。","正方形額外要求四邊等長。","選 A。"], "easy"),
]

